// Chat-completion presets (SillyTavern prompt manager format).

export const MARKER_LABELS = {
  main: 'Main prompt',
  nsfw: 'Auxiliary prompt',
  jailbreak: 'Post-history instructions',
  enhanceDefinitions: 'Enhance definitions',
  worldInfoBefore: 'Lorebook entries (before)',
  worldInfoAfter: 'Lorebook entries (after)',
  charDescription: 'Character description',
  charPersonality: 'Character personality',
  scenario: 'Scenario',
  personaDescription: 'Persona description',
  dialogueExamples: 'Example dialogue',
  chatHistory: 'Chat history',
};
// Slots whose content is generated by the app (not editable text).
export const AUTO_SLOTS = new Set(['worldInfoBefore', 'worldInfoAfter', 'charDescription', 'charPersonality', 'scenario', 'personaDescription', 'dialogueExamples', 'chatHistory']);

// SillyTavern's defaults
export const DEFAULT_CONTINUE = '[Continue your last message without repeating its original content.]';
export const DEFAULT_IMPERSONATE = "[Write your next reply from the point of view of {{user}}, using the chat history so far as a guideline for the writing style of {{user}}. Don't write as {{char}} or system. Don't describe actions of {{char}}.]";
export const DEFAULT_GROUP_NUDGE = '[Write the next reply only as {{char}}.]';

const EFFORT_MAP = { minimum: 'low', min: 'low', low: 'low', medium: 'medium', high: 'high', maximum: 'max', max: 'max' };

export function isSTPreset(json) {
  return json && Array.isArray(json.prompts) && Array.isArray(json.prompt_order);
}

export function importSTPreset(json, name, id) {
  if (!isSTPreset(json)) throw new Error('Not a SillyTavern chat completion preset');
  const orderObj = json.prompt_order.find((o) => String(o.character_id) === '100001')
    || json.prompt_order[json.prompt_order.length - 1];
  const prompts = json.prompts.map((p) => ({
    identifier: String(p.identifier),
    name: String(p.name || MARKER_LABELS[p.identifier] || p.identifier),
    role: p.role || 'system',
    content: String(p.content || ''),
    marker: !!p.marker,
    system_prompt: !!p.system_prompt,
    injection_position: Number(p.injection_position) || 0,
    injection_depth: Number(p.injection_depth ?? 4),
    injection_order: Number(p.injection_order ?? 100),
    forbid_overrides: !!p.forbid_overrides,
  }));
  const known = new Set(prompts.map((p) => p.identifier));
  const order = (orderObj ? orderObj.order : prompts.map((p) => ({ identifier: p.identifier, enabled: true })))
    .filter((o) => known.has(o.identifier))
    .map((o) => ({ identifier: o.identifier, enabled: !!o.enabled }));
  const { prompts: _p, prompt_order: _o, ...raw } = json;
  return {
    id,
    name,
    prompts,
    order,
    formats: {
      wi_format: json.wi_format ?? '{0}',
      scenario_format: json.scenario_format ?? '{{scenario}}',
      personality_format: json.personality_format ?? '{{personality}}',
      persona_format: '{{persona}}',
    },
    new_chat_prompt: json.new_chat_prompt || '',
    continue_nudge_prompt: json.continue_nudge_prompt || DEFAULT_CONTINUE,
    continue_postfix: typeof json.continue_postfix === 'string' ? json.continue_postfix : ' ',
    impersonation_prompt: json.impersonation_prompt || DEFAULT_IMPERSONATE,
    group_nudge_prompt: json.group_nudge_prompt || DEFAULT_GROUP_NUDGE,
    new_example_chat_prompt: json.new_example_chat_prompt || '[Example Chat]',
    samplers: {
      temperature: num(json.temperature),
      top_p: num(json.top_p),
      top_k: num(json.top_k),
      min_p: num(json.min_p),
      frequency_penalty: num(json.frequency_penalty),
      presence_penalty: num(json.presence_penalty),
      repetition_penalty: num(json.repetition_penalty),
      max_tokens: num(json.openai_max_tokens),
      context_size: num(json.openai_max_context),
      claude_effort: EFFORT_MAP[String(json.reasoning_effort || '').toLowerCase()] ?? '',
      show_thoughts: typeof json.show_thoughts === 'boolean' ? json.show_thoughts : undefined,
    },
    raw,
    importedAt: Date.now(),
  };
}

function num(v) {
  const n = Number(v);
  return Number.isFinite(n) ? n : undefined;
}

export function exportSTPreset(p) {
  return {
    ...p.raw,
    prompts: p.prompts.map((x) => ({
      identifier: x.identifier, name: x.name, role: x.role, content: x.content, marker: x.marker,
      system_prompt: x.system_prompt, injection_position: x.injection_position, injection_depth: x.injection_depth,
      injection_order: x.injection_order, forbid_overrides: x.forbid_overrides,
    })),
    prompt_order: [{ character_id: 100001, order: p.order }],
  };
}

/** The built-in "Simple" preset, generated from Settings → Prompts. */
export function simplePreset(promptSettings) {
  const prompts = [
    { identifier: 'main', name: 'Main prompt', role: 'system', content: promptSettings.main || '' },
    { identifier: 'worldInfoBefore', marker: true },
    { identifier: 'personaDescription', marker: true },
    { identifier: 'charDescription', marker: true },
    { identifier: 'charPersonality', marker: true },
    { identifier: 'scenario', marker: true },
    { identifier: 'worldInfoAfter', marker: true },
    { identifier: 'dialogueExamples', marker: true },
    { identifier: 'chatHistory', marker: true },
    { identifier: 'jailbreak', name: 'Post-history', role: 'system', content: promptSettings.post_history || '' },
  ].map((p) => ({ role: 'system', content: '', injection_position: 0, injection_depth: 4, injection_order: 100, name: MARKER_LABELS[p.identifier], ...p }));
  return {
    id: '__simple',
    name: 'Simple',
    prompts,
    order: prompts.map((p) => ({ identifier: p.identifier, enabled: true })),
    formats: {
      wi_format: '{0}',
      scenario_format: 'Scenario: {{scenario}}',
      personality_format: "{{char}}'s personality: {{personality}}",
      persona_format: 'About {{user}}: {{persona}}',
    },
    new_chat_prompt: '',
    new_example_chat_prompt: 'Example dialogue (style reference only, not part of the story):',
    continue_nudge_prompt: DEFAULT_CONTINUE,
    continue_postfix: ' ',
    impersonation_prompt: DEFAULT_IMPERSONATE,
    group_nudge_prompt: DEFAULT_GROUP_NUDGE,
  };
}
